message.content:
{
  "css": ".day-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.day-tabs button {
  flex: 0 0 auto;
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  border-radius: 16px;
  border: 1px solid #e8e8e8;
  background-color: #fff;
  color: #111;
  font-weight: 700;
  font-size: 14px;
  line-height: 32px;
  cursor: default;
  text-align: center;
}

.day-tabs button[aria-pressed="true"] {
  background-color: #111;
  color: #fff;
  border-color: #111;
}

.day-tabs button[disabled] {
  opacity: 1;
}"
}
